class Solution {
    private long cost(int value,int k){
        return Math.max(0L,(long)k-value);
    }
    public long minIncrementOperations(int[] nums,int k){
        long first=cost(nums[0],k),second=cost(nums[1],k),third=cost(nums[2],k);
        for(int i=3;i<nums.length;i++){
            long current=cost(nums[i],k)+Math.min(first,Math.min(second,third));
            first=second;
            second=third;
            third=current;
        }
        return Math.min(first,Math.min(second,third));
    }
}

code.kotlin:
class Solution {
    private fun cost(value:Int,k:Int)=maxOf(0L,k.toLong()-value);
    fun minIncrementOperations(nums:IntArray,k:Int):Long{
        var first=cost(nums[0],k);
        var second=cost(nums[1],k);
        var third=cost(nums[2],k);
        for(i in 3 until nums.size){
            val current=cost(nums[i],k)+minOf(first,second,third);
            first=second;
            second=third;
            third=current
        };
        return minOf(first,second,third)
    }
}

